/* @lc app=leetcode id=2561 lang=kotlin */ class Solution { fun minCost(basket1: IntArray, basket2: IntArray): Long = basket1.toList().groupingBy { it }.eachCount().toMutableMap().also { c -> basket2.forEach { c.merge(it, -1) { a, b -> a + b } } }.let { d -> if (d.values.any { it % 2 != 0 }) -1L else d.flatMap { (x, c) -> List(Math.abs(c) / 2) { x } }.sorted().let { l -> minOf(basket1.min(), basket2.min()).let { m -> l.take(l.size / 2).sumOf { minOf(it, 2 * m).toLong() } } } } }